   140  static char *
   141  strsep_char(char *strp, const char *end, char delim)
   142  {
   143      char *ptr;
   144
   145      if (UNLIKELY(!strp))
   146          return NULL;
   147
   148      ptr = strchr(strp, delim);
   149      if (UNLIKELY(!ptr))
   150          return NULL;
   151
   152      if (UNLIKELY(ptr > end))
   153          return NULL;
   154
   155      *ptr = '\0';
   156      return ptr + 1;
   157  }
