   159  static char *
   160  parse_proxy_protocol_v1(struct lwan_request *request, char *buffer)
   161  {
   162      static const size_t line_size = 108;
   163      char *end, *protocol, *src_addr, *dst_addr, *src_port, *dst_port;
   164      unsigned int size;
   165      struct lwan_proxy *const proxy = request->proxy;
   166
   167      end = memchr(buffer, '\r', line_size);
   168      if (UNLIKELY(!end || end[1] != '\n'))
   169          return NULL;
   170      *end = '\0';
   171      size = (unsigned int) (end + 2 - buffer);
   172
   173      protocol = buffer + sizeof("PROXY ") - 1;
   174      src_addr = strsep_char(protocol, end, ' ');
   175      dst_addr = strsep_char(src_addr, end, ' ');
   176      src_port = strsep_char(dst_addr, end, ' ');
   177      dst_port = strsep_char(src_port, end, ' ');
   178
   179      if (UNLIKELY(!dst_port))
   180          return NULL;
   181
   182      STRING_SWITCH(protocol) {
   183      case MULTICHAR_CONSTANT('T', 'C', 'P', '4'): {
   184          struct sockaddr_in *from = &proxy->from.ipv4;
   185          struct sockaddr_in *to = &proxy->to.ipv4;
   186
   187          from->sin_family = to->sin_family = AF_INET;
   188
   189          if (UNLIKELY(inet_pton(AF_INET, src_addr, &from->sin_addr) <= 0))
   190              return NULL;
   191          if (UNLIKELY(inet_pton(AF_INET, dst_addr, &to->sin_addr) <= 0))
   192              return NULL;
   193          if (UNLIKELY(!parse_ascii_port(src_port, &from->sin_port)))
   194              return NULL;
   195          if (UNLIKELY(!parse_ascii_port(dst_port, &to->sin_port)))
   196              return NULL;
   197
   198          break;
   199      }
   200      case MULTICHAR_CONSTANT('T', 'C', 'P', '6'): {
   201          struct sockaddr_in6 *from = &proxy->from.ipv6;
   202          struct sockaddr_in6 *to = &proxy->to.ipv6;
   203
   204          from->sin6_family = to->sin6_family = AF_INET6;
   205
   206          if (UNLIKELY(inet_pton(AF_INET6, src_addr, &from->sin6_addr) <= 0))
   207              return NULL;
   208          if (UNLIKELY(inet_pton(AF_INET6, dst_addr, &to->sin6_addr) <= 0))
   209              return NULL;
   210          if (UNLIKELY(!parse_ascii_port(src_port, &from->sin6_port)))
   211              return NULL;
   212          if (UNLIKELY(!parse_ascii_port(dst_port, &to->sin6_port)))
   213              return NULL;
   214
   215          break;
   216      }
   217      default:
   218          return NULL;
   219      }
